  <p class="item">copper</p>
  <p class="item">nickel</p>
  <p class="item">osmium</p>
  <p class="item">pewter</p>
</article>
<script>
const field = document.getElementById('input-term');
const rows = Array.from(document.querySelectorAll('#listing .item'));
function display() {
  const q = field.value.toLowerCase();
  rows.forEach(function (el) {
    const hit = el.textContent.toLowerCase().indexOf(q) !== -1;
    el.className = hit ? 'item' : 'item gone';
  });
}
field.addEventListener('keyup', display);
</script>
</body>
</html>`)
